18	// ep builds an endpoint; gw and ip may be empty (no address).
19	func ep(name, ip, gw string, prio *int) docker.EndpointNetwork {
20		e := docker.EndpointNetwork{Name: name, GwPriority: prio}
21		if ip != "" {
22			e.IPv4 = netip.MustParseAddr(ip)
