30	func TestPathContainerDefaultRouteNetwork(t *testing.T) {
31		a0 := ep("a", "172.18.0.5", "172.18.0.1", prioOf(0))
32		b10 := ep("b", "172.19.0.5", "172.19.0.1", prioOf(10))
33		tests := []struct {
34			name   string
35			nets   []docker.EndpointNetwork
36			want   string // "" means not found
37			wantOK bool
38		}{
39			{"one endpoint with a gateway", []docker.EndpointNetwork{a0}, "a", true},
40			{"one endpoint with a gateway and no priority",
41				[]docker.EndpointNetwork{ep("a", "172.18.0.5", "172.18.0.1", nil)}, "a", true},
42			{"an internal network cannot hold the default route",
43				[]docker.EndpointNetwork{a0, ep("b", "10.0.0.2", "", prioOf(50))}, "a", true},
44			{"the strictly highest priority wins", []docker.EndpointNetwork{a0, b10}, "b", true},
45			{"the strictly highest priority wins whatever the order", []docker.EndpointNetwork{b10, a0}, "b", true},
46			{"a tie is never guessed (H8)", []docker.EndpointNetwork{
47				ep("a", "172.18.0.5", "172.18.0.1", prioOf(5)),
48				ep("b", "172.19.0.5", "172.19.0.1", prioOf(5)),
49			}, "", false},
50			{"a tie at the top is never guessed", []docker.EndpointNetwork{
51				ep("a", "172.18.0.5", "172.18.0.1", prioOf(1)),
52				ep("b", "172.19.0.5", "172.19.0.1", prioOf(7)),
53				ep("c", "172.20.0.5", "172.20.0.1", prioOf(7)),
54			}, "", false},
55			{"a priority missing on one candidate is never guessed", []docker.EndpointNetwork{
56				ep("a", "172.18.0.5", "172.18.0.1", nil),
57				ep("b", "172.19.0.5", "172.19.0.1", prioOf(3)),
58			}, "", false},
59			{"no priority on any candidate is never guessed", []docker.EndpointNetwork{
60				ep("a", "172.18.0.5", "172.18.0.1", nil),
61				ep("b", "172.19.0.5", "172.19.0.1", nil),
62			}, "", false},
63			{"no gateway anywhere", []docker.EndpointNetwork{
64				ep("a", "172.18.0.5", "", prioOf(0)),
65				ep("b", "172.19.0.5", "", prioOf(1)),
66			}, "", false},
67			{"no endpoint", nil, "", false},
68		}
69		for _, tt := range tests {
70			t.Run(tt.name, func(t *testing.T) {
71				before := slices.Clone(tt.nets)
72				got, ok := defaultRouteNetwork(tt.nets)
73				if ok != tt.wantOK || got.Name != tt.want {
74					t.Fatalf("defaultRouteNetwork = (%q, %v), want (%q, %v)", got.Name, ok, tt.want, tt.wantOK)
75				}
76				if !slices.EqualFunc(tt.nets, before, func(x, y docker.EndpointNetwork) bool {
77					return x.Name == y.Name && x.IPv4 == y.IPv4 && x.Gateway == y.Gateway
78				}) {
79					t.Errorf("defaultRouteNetwork modified its input")
80				}
81			})
82		}
83	}
