48	// newPathContainer converts an inspection into a pathContainer. Every text the
49	// engine returned is sanitized here, so the cells are display-safe.
50	func newPathContainer(src pathSource, n docker.ContainerNetworking, err error) pathContainer {
51		c := pathContainer{Name: src.Name, Attach: attachUndetermined}
52		if err != nil {
53			return c
54		}
55		c.Known = true
56		if name := engineText(n.Name); name != "" {
57			c.Name = name
58		}
59		c.Running = n.Running
60		if !n.Running {
61			return c
62		}
63		switch {
64		case n.Mode == modeHost:
65			c.Attach = attachHost
66		case n.Mode == modeNone:
67			c.Attach = attachNone
68		case strings.HasPrefix(n.Mode, modeSharedPrefix):
69			c.Attach = attachShared
70		default:
71			c.Networks = len(n.Networks)
72			if picked, ok := defaultRouteNetwork(n.Networks); ok {
73				c.Attach = attachNetwork
74				c.Network = engineText(picked.Name)
75				c.Addr = picked.IPv4
76				c.Gateway = picked.Gateway
77			}
78		}
79		return c
80	}
